<template>
  <div class="agent-config-step">

    <div class="config-sections">
      <!-- Model Configuration -->
      <q-card flat bordered class="config-section q-mb-md">
        <q-card-section>
          <div class="section-title">
            <q-icon name="psychology" size="24px" class="q-mr-sm" />
            {{ $t('model_configuration') }}
          </div>
        </q-card-section>
        <q-card-section class="q-pt-none">
          <div class="config-grid">
            <q-select
              v-model="localConfig.reasoning_effort"
              :options="effortOptions"
              :label="$t('reasoning_effort')"
              outlined
              dense
              emit-value
              map-options
              @update:model-value="emitUpdate"
            >
              <template v-slot:option="scope">
                <q-item v-bind="scope.itemProps">
                  <q-item-section>
                    <q-item-label>{{ scope.opt.label }}</q-item-label>
                    <q-item-label caption>{{ scope.opt.description }}</q-item-label>
                  </q-item-section>
                </q-item>
              </template>
            </q-select>
            <div class="text-caption text-grey">
              {{ $t('reasoning_effort_hint') }}
            </div>

          </div>
        </q-card-section>
      </q-card>

      <!-- Approval Mode -->
      <q-card flat bordered class="config-section q-mb-md">
        <q-card-section>
          <div class="section-title">
            <q-icon name="verified_user" size="24px" class="q-mr-sm" />
            {{ $t('approval_settings') }}
          </div>
        </q-card-section>
        <q-card-section class="q-pt-none">
          <div class="text-caption text-grey q-mb-md">
            {{ $t('approval_settings_description') }}
          </div>
          <q-btn-toggle
            v-model="localConfig.approval_mode"
            :options="approvalModeOptions"
            no-caps
            rounded
            unelevated
            toggle-color="primary"
            color="white"
            text-color="primary"
            @update:model-value="emitUpdate"
          />
        </q-card-section>
      </q-card>

    </div>
  </div>
</template>

<script lang="ts">
import { defineComponent, ref, watch, computed, PropType } from 'vue';
import { useTranslate } from '@tolgee/vue';
import type { AgentConfig } from 'src/@types/agents';

export default defineComponent({
  name: 'AgentConfigStep',

  props: {
    modelValue: {
      type: Object as PropType<AgentConfig>,
      required: true,
    },
  },

  emits: ['update:modelValue'],

  setup(props, { emit }) {
    const { t } = useTranslate();
    const localConfig = ref<AgentConfig>({ ...props.modelValue });

    // One model; capability/cost is dialed with reasoning effort. Higher
    // effort spends more reasoning/output tokens (billed 1:1), so cost
    // scales with the chosen effort.
    const effortOptions = computed(() =>
      ['none', 'low', 'medium', 'high', 'xhigh'].map((value) => ({
        value,
        label: t.value(`effort_${value}_label`),
        description: t.value(`effort_${value}_desc`),
      })),
    );

    watch(
      () => props.modelValue,
      (newVal) => {
        localConfig.value = { ...newVal };
      },
      { deep: true }
    );

    const emitUpdate = () => {
      emit('update:modelValue', { ...localConfig.value });
    };

    const approvalModeOptions = computed(() => [
      { label: t.value('approval_mode_none'), value: 'none' },
      { label: t.value('approval_mode_critical'), value: 'critical' },
      { label: t.value('approval_mode_all'), value: 'all' },
    ]);

    return {
      localConfig,
      effortOptions,
      approvalModeOptions,
      emitUpdate,
    };
  },
});
</script>

