<template>
  <div class="agent-instructions-step">

    <!-- Role-specific hint -->
    <q-banner v-if="roleHint" class="role-hint q-mb-md" rounded>
      <template v-slot:avatar>
        <q-icon :name="roleHint.icon" color="primary" />
      </template>
      {{ roleHint.text }}
    </q-banner>

    <div
      class="instructions-container"
      :class="{ 'instructions-container--no-variables': !availableVariables.length }"
    >
      <!-- System Prompt Editor -->
      <div class="prompt-editor">
        <div class="text-subtitle2 q-mb-sm">{{ $t('system_prompt') }} *</div>
        <q-input
          v-model="localPrompt"
          type="textarea"
          outlined
          :placeholder="$t('system_prompt_placeholder')"
          rows="15"
          :maxlength="AGENT_PROMPT_MAX_LENGTH"
          counter
          :error="promptTooShort"
          :error-message="promptTooShort
            ? $t('agent_wizard_min_length_live', {
                min: AGENT_PROMPT_MIN_LENGTH,
                count: localPrompt.trim().length,
              })
            : ''"
          class="prompt-textarea"
          @update:model-value="emitUpdate"
        />
      </div>

      <!-- Available Variables — hidden when there are no real variables
           to offer (e.g. specialist role).  Panel is purely informative;
           an empty panel that still says "click a variable" would lie. -->
      <div v-if="availableVariables.length" class="variables-panel">
        <div class="text-subtitle2 q-mb-sm">{{ $t('available_variables') }}</div>
        <div class="variables-list">
          <q-chip
            v-for="variable in availableVariables"
            :key="variable.name"
            clickable
            color="grey-3"
            text-color="grey-8"
            size="sm"
            @click="insertVariable(variable.name)"
          >
            {{ variable.name }}
            <q-tooltip>{{ variable.description }}</q-tooltip>
          </q-chip>
        </div>

        <div class="text-caption text-grey q-mt-md">
          {{ $t('click_to_insert_variable') }}
        </div>
      </div>
    </div>
  </div>
</template>

<script lang="ts">
import { computed, defineComponent, ref, watch } from 'vue';
import { useTranslate } from '@tolgee/vue';
import {
  AGENT_PROMPT_MAX_LENGTH,
  AGENT_PROMPT_MIN_LENGTH,
} from './agent-wizard-constants';

export default defineComponent({
  name: 'AgentInstructionsStep',

  props: {
    modelValue: {
      type: String,
      required: true,
    },
    role: {
      type: String,
      default: 'specialist',
    },
  },

  emits: ['update:modelValue'],

  setup(props, { emit }) {
    const { t } = useTranslate();
    const localPrompt = ref(props.modelValue);

    const AGENT_DESCRIPTIONS_VARIABLE = '{agent_descriptions}';

    const ROLE_HINT_ICONS: Record<string, string> = {
      orchestrator: 'account_tree',
      specialist: 'smart_toy',
    };

    const roleHint = computed(() => {
      const role = ROLE_HINT_ICONS[props.role] ? props.role : 'specialist';
      return {
        icon: ROLE_HINT_ICONS[role],
        text: t.value(`agent_wizard_prompt_hint_${role}`, { variable: AGENT_DESCRIPTIONS_VARIABLE }),
      };
    });

    // Only `{agent_descriptions}` is genuinely substituted at runtime —
    // ``orchestrator.py`` calls ``base_prompt.format(agent_descriptions=...)``
    // before sending the prompt.  The previous variant of this panel
    // advertised seven `{{double-brace}}` variables (org_name,
    // document_type, supplier_name, total_amount, document_fields,
    // document_id, document_status) which no code path substitutes — they
    // were inserted into prompts as literal strings and the LLM either
    // ignored them or hallucinated values.  Specialist agents already
    // get document context via ``_build_instructions``'s ``--- Context ---``
    // block (a readable text append, not a placeholder), so removing
    // the false advertisements doesn't take any feature away.
    //
    // Specialists therefore have no variables panel — the empty list
    // hides the panel entirely (see template ``v-if`` on
    // ``availableVariables.length``).  When real ``{{var}}``
    // substitution lands, repopulate this list to match.
    const availableVariables = computed(() =>
      props.role === 'orchestrator'
        ? [
            {
              name: '{agent_descriptions}',
              description: t.value('agent_wizard_variable_agent_descriptions'),
            },
          ]
        : [],
    );

    watch(
      () => props.modelValue,
      (newVal) => {
        localPrompt.value = newVal;
      }
    );

    const emitUpdate = () => {
      emit('update:modelValue', localPrompt.value);
    };

    const insertVariable = (variable: string) => {
      // Insert at cursor position or append
      localPrompt.value += ` ${variable}`;
      emitUpdate();
    };

    // Inline error indicator: HTML maxlength clamps long pastes, but
    // there's no equivalent for "too short" — surface it as a field
    // error so the user sees the constraint before clicking Next.
    // Empty (untouched) drafts don't show the error; only typed-too-short.
    const promptTooShort = computed(() => {
      const len = localPrompt.value.trim().length;
      return len > 0 && len < AGENT_PROMPT_MIN_LENGTH;
    });

    return {
      localPrompt,
      roleHint,
      availableVariables,
      emitUpdate,
      insertVariable,
      AGENT_PROMPT_MAX_LENGTH,
      AGENT_PROMPT_MIN_LENGTH,
      promptTooShort,
    };
  },
});
</script>

