<template>
  <div class="agent-basic-info-step">
    <q-form class="form-content">
      <!-- Agent Role -->
      <div class="q-mb-lg">
        <div class="text-subtitle2 q-mb-sm">{{ $t('agent_wizard_role_question') }}</div>
        <div class="role-cards">
          <div
            v-for="role in roleOptions"
            :key="role.value"
            class="role-card"
            :class="{ 'role-card--selected': localData.config.role === role.value }"
            @click="selectRole(role.value)"
          >
            <q-icon :name="role.icon" size="28px" :color="localData.config.role === role.value ? 'primary' : 'grey-6'" />
            <div class="role-card__name">{{ role.label }}</div>
            <div class="role-card__desc">{{ role.description }}</div>
          </div>
        </div>
      </div>

      <!-- Agent Name -->
      <q-input
        v-model="localData.name"
        :label="`${$t('agent_name')} *`"
        outlined
        dense
        :maxlength="AGENT_NAME_MAX_LENGTH"
        counter
        :error="!!errors.name"
        :error-message="errors.name"
        class="q-mb-md agent-name-input"
        @update:model-value="emitUpdate"
      >
        <template v-slot:prepend>
          <q-icon name="smart_toy" />
        </template>
      </q-input>

      <!-- Description -->
      <q-input
        v-model="localData.description"
        :label="descriptionLabel"
        :hint="descriptionHint"
        outlined
        dense
        type="textarea"
        rows="3"
        :maxlength="AGENT_DESCRIPTION_MAX_LENGTH"
        counter
        :error="descriptionTooShort || !!errors.description"
        :error-message="descriptionTooShort
          ? $t('agent_wizard_min_length_live', {
              min: AGENT_DESCRIPTION_MIN_LENGTH_WHEN_REQUIRED,
              count: (localData.description || '').trim().length,
            })
          : (errors.description || '')"
        class="q-mb-md"
        @update:model-value="emitUpdate"
      >
        <template v-slot:prepend>
          <q-icon name="notes" />
        </template>
      </q-input>

      <!-- Reports To (only for specialists) -->
      <!-- Reports To (specialists only, multi-select) -->
      <q-select
        v-if="isSpecialistRole"
        v-model="localData.config.reports_to"
        :options="reportsToOptions"
        :label="$t('agent_wizard_reports_to')"
        :hint="$t('agent_wizard_reports_to_hint')"
        outlined
        dense
        emit-value
        map-options
        multiple
        clearable
        use-chips
        class="q-mb-md"
        @update:model-value="emitUpdate"
      />

      <!-- Enable Agent (orchestrators only) -->
      <q-toggle
        v-if="localData.config.role === 'orchestrator'"
        v-model="localData.is_enabled"
        :label="$t('enable_agent')"
        color="positive"
        @update:model-value="emitUpdate"
      />
    </q-form>
  </div>
</template>

<script lang="ts">
import { computed, defineComponent, ref, watch, onMounted, PropType } from 'vue';
import { useTranslate } from '@tolgee/vue';
import type { AgentConfig } from 'src/@types/agents';
import DocNetAgentProfileService from 'src/services/docnet/DocNetAgentProfileService';
import {
  AGENT_NAME_MAX_LENGTH,
  AGENT_DESCRIPTION_MAX_LENGTH,
  AGENT_DESCRIPTION_MIN_LENGTH_WHEN_REQUIRED,
} from './agent-wizard-constants';

export interface FormData {
  name: string;
  description: string;
  document_types: string[];
  config: AgentConfig;
  is_enabled: boolean;
}

const ROLE_CARDS = [
  {
    value: 'orchestrator',
    icon: 'account_tree',
    labelKey: 'docnet_orchestrator',
    descriptionKey: 'agent_wizard_role_orchestrator_desc',
  },
  {
    value: 'specialist',
    icon: 'smart_toy',
    labelKey: 'agent_wizard_role_specialist',
    descriptionKey: 'agent_wizard_role_specialist_desc',
  },
];

export default defineComponent({
  name: 'AgentBasicInfoStep',

  props: {
    modelValue: {
      type: Object as PropType<FormData>,
      required: true,
    },
    errors: {
      type: Object as PropType<Record<string, string>>,
      default: () => ({}),
    },
  },

  emits: ['update:modelValue'],

  setup(props, { emit }) {
    const { t } = useTranslate();
    const localData = ref({ ...props.modelValue });
    const reportsToOptions = ref<{ label: string; value: string }[]>([]);

    const roleOptions = computed(() =>
      ROLE_CARDS.map((card) => ({
        value: card.value,
        icon: card.icon,
        label: t.value(card.labelKey),
        description: t.value(card.descriptionKey),
      })),
    );

    // Ensure config exists
    if (!localData.value.config) {
      localData.value.config = {} as AgentConfig;
    }
    if (!localData.value.config.role) {
      localData.value.config.role = 'specialist';
    }

    onMounted(async () => {
      try {
        const service = new DocNetAgentProfileService();
        const profiles = await service.getProfiles();
        reportsToOptions.value = profiles
          .filter((p) => p.role === 'orchestrator')
          .map((p) => ({ label: p.agent.name, value: p.agent.id }));
      } catch {
        // Silently fail
      }
    });

    watch(
      () => props.modelValue,
      (newVal) => {
        localData.value = { ...newVal };
      },
      { deep: true },
    );

    const emitUpdate = () => {
      emit('update:modelValue', { ...props.modelValue, ...localData.value });
    };

    const selectRole = (role: string) => {
      localData.value.config = { ...localData.value.config, role };
      // Clear reports_to if switching to orchestrator
      if (role === 'orchestrator') {
        localData.value.config.reports_to = null;
      }
      emitUpdate();
    };

    const isSpecialistRole = computed(() => {
      const role = localData.value.config?.role;
      return role !== 'orchestrator' && role !== 'router';
    });

    // Role-aware label + hint for the description field.  Orchestrators
    // are picked by the System Router from their description; specialists
    // are picked by an orchestrator from theirs.  Surface that purpose in
    // the UI so admins understand WHY description matters — and the
    // wizard's required-length check (in AgentWizard.validateCurrentStep)
    // matches this same role split.

    // Description is always required from this wizard.  The router
    // role isn't selectable here — it's a single system-org-seeded
    // agent (``system-router``), customised through its Custom
    // Instructions overlay rather than created via this flow — so
    // we don't carve out an "optional" branch for it.
    const descriptionLabel = computed(() => `${t.value('description')} *`);

    const descriptionHint = computed(() => {
      const role = localData.value.config?.role;
      if (role === 'orchestrator') {
        return t.value('agent_wizard_description_hint_orchestrator');
      }
      // Specialist (default for everything else this wizard creates)
      return t.value('agent_wizard_description_hint_specialist');
    });

    // Live "too short" indicator — same pattern as the system_prompt
    // editor in AgentInstructionsStep.  Shows the error AS SOON AS the
    // user types something below the threshold; clears the moment
    // they cross it.  Untouched (empty) drafts don't flag inline —
    // the wizard's Next-button validation reports "required" when
    // appropriate, so empty has its own path.
    const descriptionTooShort = computed(() => {
      const len = (localData.value.description || '').trim().length;
      return len > 0 && len < AGENT_DESCRIPTION_MIN_LENGTH_WHEN_REQUIRED;
    });

    return {
      localData,
      roleOptions,
      reportsToOptions,
      isSpecialistRole,
      emitUpdate,
      selectRole,
      AGENT_NAME_MAX_LENGTH,
      AGENT_DESCRIPTION_MAX_LENGTH,
      AGENT_DESCRIPTION_MIN_LENGTH_WHEN_REQUIRED,
      descriptionLabel,
      descriptionHint,
      descriptionTooShort,
    };
  },
});
</script>

