/**
 * Agent-wizard validation limits.
 *
 * These mirror the Pydantic ``Field`` constraints on
 * ``AgentCreate`` / ``AgentUpdate`` in the backend
 * (``src/models/agent.py``).  Hand-maintained — keep in sync.  Drift
 * surfaces as a backend 422 with a vague "internal error" toast on
 * save, which is the bug these constants exist to prevent.
 *
 * Pattern matches existing wizard-local constants in the app
 * (e.g. ``NOTE_MAX_LENGTH`` in workflow-advanced-models.ts).  No
 * shared validation library yet — see DOCB design notes for the
 * larger schema-driven-validation discussion.
 */

export const AGENT_NAME_MAX_LENGTH = 100;
export const AGENT_NAME_MIN_LENGTH = 1;
export const AGENT_DESCRIPTION_MAX_LENGTH = 500;

/**
 * Minimum description length when description is required (orchestrators
 * + specialists).  The router and parent orchestrators select agents
 * solely from this text, so a fragment like "Validates invoices" tells
 * the LLM what the agent does but not WHEN to delegate to it (vs other
 * validators in the org).  60 chars forces at least a full sentence
 * carrying both pieces — what the agent does AND when it applies —
 * which is the threshold where description starts pulling its weight
 * for routing.
 *
 * Backend mirrors this on ``AgentCreate`` via a model_validator (see
 * ``src/models/agent.py``) — if you change this number, change it
 * there too.  Wizard checks live as the user types; backend is the
 * defense-in-depth for direct API callers.
 */
export const AGENT_DESCRIPTION_MIN_LENGTH_WHEN_REQUIRED = 60;

export const AGENT_PROMPT_MAX_LENGTH = 10000;

/**
 * Minimum system_prompt length.  Backend ``Field(min_length=10)`` lets
 * "Be helpful." through — technically valid but produces an agent that
 * can't reliably do anything.  The wizard's role hint asks the user to
 * describe four things (the task, input expectations, processing steps,
 * and output format) — 150 chars is the floor where all four can fit
 * without contortion ("Validate X. Inputs: Y. Steps: Z. Output: W.").
 * Below that the prompt either drops one of the four or the wizard's
 * own guidance is impossible to follow.
 *
 * Stays below the 10000-char max with plenty of headroom; every system
 * agent in default_agents.py is multiple paragraphs, so 150 doesn't
 * block any realistic specialist.
 *
 * Wizard-only — backend's 10-char floor stays as the looser safety net
 * so legacy agents with short prompts can still be edited.
 */
export const AGENT_PROMPT_MIN_LENGTH = 150;
