<template>
  <div class="skill-selector">
    <!-- Single tree view — skill groups with parent checkbox +
         per-tool rows (name chip + critical toggle).  Replaces
         the previous skill-cards UI; the same component handles
         skill on/off (group checkbox toggles all tools at once)
         and per-tool customization. -->
    <McpToolSelector
      v-if="mcpServers !== undefined"
      :model-value="mcpServers"
      :skills="modelValue"
      :available-skills="skillDefinitions"
      :mcp-tools="tools"
      :agent-id="agentId"
      :approval-mode="approvalMode"
      :local-overrides="localOverrides"
      @update:model-value="$emit('update:mcpServers', $event)"
      @update:tools="$emit('update:tools', $event)"
      @update:local-overrides="$emit('update:localOverrides', $event)"
    />
  </div>
</template>

<script lang="ts">
import { defineComponent, ref, computed, watch, PropType } from 'vue';
import { useTranslate } from '@tolgee/vue';
import type { AgentSkill, SkillDefinition } from 'src/@types/agents';
import { useAgentsStore } from 'src/store/Settings/agents.store';
import McpToolSelector from './McpToolSelector.vue';
import { skillDescription, skillLabel } from 'src/pages/DocNet/shared/docnet-labels';

// Fallback skill definitions used when the API hasn't loaded yet.
// The `tools` arrays are populated from the /agents/skills API response.
const DEFAULT_SKILL_IDS = [
  'channel_notification',
  'document_extraction',
  'document_classification',
  'field_validation',
  'master_data_lookup',
  'po_matching',
  'translation',
  'summarization',
  'custom_script',
  'orchestration',
  'email_classification',
  'email_reply',
];

export default defineComponent({
  name: 'SkillSelector',

  components: { McpToolSelector },

  props: {
    modelValue: {
      type: Array as PropType<AgentSkill[]>,
      required: true,
    },
    availableSkills: {
      type: Array as PropType<SkillDefinition[]>,
      default: () => [],
    },
    role: {
      type: String,
      default: 'specialist',
    },
    tools: {
      type: Array as PropType<string[]>,
      default: () => [],
    },
    mcpServers: {
      type: Object as PropType<Record<string, string[]>>,
      default: undefined,
    },
    /** Agent id when editing an existing agent — needed to read/write
     *  per-tool approval overrides.  ``null`` during the create
     *  wizard (no agent yet); the override popover degrades gracefully
     *  to read-only in that case. */
    agentId: {
      type: String as PropType<string | null>,
      default: null,
    },
    /** Current ``approval_mode`` of the agent — used by the chip
     *  to decide whether overrides apply (only under ``critical``). */
    approvalMode: {
      type: String,
      default: 'critical',
    },
    /** Buffered ``tool_approvals`` map for the create wizard.
     *  Forwarded to the tool toggles so they can read/write
     *  without going through the API. */
    localOverrides: {
      type: Object as PropType<Record<string, boolean> | null>,
      default: null,
    },
  },

  emits: [
    'update:modelValue',
    'update:tools',
    'update:mcpServers',
    'update:localOverrides',
  ],

  setup(props, { emit }) {
    const { t } = useTranslate();
    const agentsStore = useAgentsStore();
    // Make sure the critical-tools metadata is loaded — the
    // skill cards render tool chips and need the flag to color
    // critical tools amber.  Idempotent: a no-op if already
    // cached.  Errors are swallowed inside the store action so
    // the wizard still works (chips just stay neutral).
    agentsStore.fetchToolMetadata();

    // Pre-load per-agent overrides so the badge popover renders
    // the correct initial state (default vs require vs skip).  No-op
    // when ``agentId`` is null (create wizard).
    if (props.agentId) {
      agentsStore.fetchToolApprovals(props.agentId);
    }

    const localSkills = ref<AgentSkill[]>([...props.modelValue]);
    const skillDefinitions = computed<SkillDefinition[]>(() => {
      const source = props.availableSkills.length > 0
        ? props.availableSkills
        : DEFAULT_SKILL_IDS.map((id) => ({ id, name: '', description: '', tools: [] }));
      return source.map((def) => ({
        ...def,
        name: skillLabel(t.value, def.id),
        description: skillDescription(t.value, def.id),
      }));
    });

    const enabledSkills = computed(() => localSkills.value.filter((s) => s.is_enabled));
    const enabledSkillsCount = computed(() => enabledSkills.value.length);

    const isSkillEnabled = (skillId: string): boolean => {
      return localSkills.value.some((s) => s.skill_type === skillId && s.is_enabled);
    };

    const getSkillTools = (skillId: string): string[] => {
      const skill = skillDefinitions.value.find((s) => s.id === skillId);
      return skill?.tools || [];
    };

    /**
     * Compute the flat tool names list + MCP server config from all enabled skills.
     */
    const emitToolsAndMcp = () => {
      const toolSet = new Set<string>();
      const mcpMap: Record<string, Set<string>> = {};

      for (const skill of localSkills.value) {
        if (!skill.is_enabled) continue;

        // FunctionTools
        for (const tool of getSkillTools(skill.skill_type)) {
          toolSet.add(tool);
        }

        // MCP tools
        const def = skillDefinitions.value.find((s) => s.id === skill.skill_type);
        if (def?.mcp_tools) {
          for (const [serverId, tools] of Object.entries(def.mcp_tools)) {
            if (!mcpMap[serverId]) mcpMap[serverId] = new Set();
            for (const t of tools) mcpMap[serverId].add(t);
          }
        }
      }

      // Always include the HITL primitive so any agent can ask the user.
      toolSet.add('request_human_approval');

      emit('update:tools', [...toolSet]);

      // Merge skill MCP tools with any manually selected MCP tools
      const currentMcp = props.mcpServers || {};
      const merged: Record<string, string[]> = {};
      // Start with skill-derived MCP tools
      for (const [sid, toolSet] of Object.entries(mcpMap)) {
        merged[sid] = [...toolSet];
      }
      // Add any manually selected tools that aren't from skills
      for (const [sid, tools] of Object.entries(currentMcp)) {
        if (!merged[sid]) merged[sid] = [];
        for (const t of tools) {
          if (!merged[sid].includes(t)) merged[sid].push(t);
        }
      }
      // Clean up empty servers
      for (const sid of Object.keys(merged)) {
        if (merged[sid].length === 0) delete merged[sid];
      }
      emit('update:mcpServers', merged);
    };

    // Re-derive tools + mcp_servers when skills change externally
    // (covers edit-mode load and external changes)
    watch(() => props.modelValue, (newVal) => {
      localSkills.value = [...newVal];
      emitToolsAndMcp();
    }, { deep: true });

    // The McpToolSelector now drives tool-on/tool-off directly via
    // ``update:tools``.  Mirror that into ``modelValue`` (the
    // skills array) so backend skill-instruction blocks stay in
    // sync — a skill is enabled iff ≥1 of its tools is selected.
    watch(() => props.tools, (newTools) => {
      const selected = new Set(newTools || []);
      let mutated = false;
      const next: AgentSkill[] = [];
      const seen = new Set<string>();

      for (const def of skillDefinitions.value) {
        if (seen.has(def.id)) continue;
        seen.add(def.id);
        const skillTools = def.tools || [];
        const enabled = skillTools.some((t) => selected.has(t));
        const existing = localSkills.value.find((s) => s.skill_type === def.id);
        if (!existing || existing.is_enabled !== enabled) mutated = true;
        next.push({
          skill_type: def.id as any,
          is_enabled: enabled,
          config: existing?.config || {},
        });
      }
      if (mutated) {
        localSkills.value = next;
        emit('update:modelValue', [...next]);
      }
    }, { deep: true });

    const toggleSkill = (skillId: string, enabled: boolean) => {
      const existingIndex = localSkills.value.findIndex((s) => s.skill_type === skillId);
      if (existingIndex >= 0) {
        localSkills.value[existingIndex].is_enabled = enabled;
      } else if (enabled) {
        localSkills.value.push({ skill_type: skillId as any, is_enabled: true, config: {} });
      }
      emit('update:modelValue', [...localSkills.value]);
      emitToolsAndMcp();
    };

    const getSkillName = (skillType: string): string => {
      const skill = skillDefinitions.value.find((s) => s.id === skillType);
      return skill?.name || skillType;
    };

    const formatToolName = (name: string): string => {
      return name.replace(/_/g, ' ').replace(/\b\w/g, (c) => c.toUpperCase());
    };

    return {
      agentsStore,
      localSkills,
      skillDefinitions,
      enabledSkills,
      enabledSkillsCount,
      isSkillEnabled,
      getSkillTools,
      toggleSkill,
      getSkillName,
      formatToolName,
    };
  },
});
</script>

