<template>
  <div class="agent-wizard">
    <div class="wizard-layout">
      <!-- Top: Horizontal Step Indicator -->
      <div class="wizard-step-indicator">
        <div class="step-timeline">
          <template v-for="(s, index) in steps" :key="s.id">
            <div
              class="step-node"
              :class="{
                'step-node--active': step === s.id,
                'step-node--completed': step > s.id,
                'step-node--pending': step < s.id && !isEdit,
                'step-node--available': step < s.id && isEdit,
              }"
              @click="navigateToStep(s.id)"
            >
              <div class="step-dot">
                <q-icon v-if="step > s.id" name="check" size="12px" color="white" />
                <span v-else class="step-number">{{ s.id }}</span>
              </div>
              <span class="step-label">{{ $t(s.labelKey) }}</span>
            </div>
            <!-- Horizontal connecting line between dots -->
            <div
              v-if="index < steps.length - 1"
              class="step-line"
              :class="{ 'step-line--completed': step > s.id }"
            />
          </template>
        </div>
      </div>

      <!-- Content Area -->
      <div class="wizard-content">
        <div class="wizard-content-scroll">
          <q-tab-panels
            v-model="step"
            animated
            transition-prev="fade"
            transition-next="fade"
            class="bg-transparent"
          >
            <!-- Step 1: Basic Info -->
            <q-tab-panel :name="1" class="q-pa-none">
              <div class="step-title q-mb-sm">{{ $t('basic_info') }}</div>
              <p class="step-subtitle q-mb-lg">
                {{ $t('basic_info_step_desc') }}
              </p>
              <AgentBasicInfoStep
                v-model="formData"
                :errors="errors"
              />
            </q-tab-panel>

            <!-- Step 2: Instructions -->
            <q-tab-panel :name="2" class="q-pa-none">
              <div class="step-title q-mb-sm">{{ $t('instructions') }}</div>
              <p class="step-subtitle q-mb-lg">
                {{ $t('instructions_step_desc') }}
              </p>
              <AgentInstructionsStep
                v-model="formData.system_prompt"
                :role="formData.config?.role || 'specialist'"
              />
            </q-tab-panel>

            <!-- Step 3: Skills -->
            <q-tab-panel :name="3" class="q-pa-none">
              <div class="step-title q-mb-sm">{{ $t('skills') }}</div>
              <p class="step-subtitle q-mb-lg">
                {{ $t('skills_step_desc') }}
              </p>
              <SkillSelector
                v-model="formData.skills"
                v-model:tools="formData.tools"
                v-model:mcp-servers="formData.mcp_servers"
                v-model:local-overrides="formData.tool_approvals"
                :available-skills="availableSkills"
                :role="formData.config?.role || 'specialist'"
                :agent-id="null"
                :approval-mode="formData.config?.approval_mode || 'critical'"
              />
            </q-tab-panel>

            <!-- Step 4: Agent Pool (orchestrator only) -->
            <q-tab-panel v-if="isOrchestrator" :name="4" class="q-pa-none">
              <div class="step-title q-mb-sm">{{ $t('docnet_agent_pool') }}</div>
              <p class="step-subtitle q-mb-lg">
                {{ $t('agent_wizard_agent_pool_subtitle') }}
              </p>
              <div class="agent-pool-grid">
                <q-card
                  v-for="p in poolAgents"
                  :key="p.agent.id"
                  flat
                  bordered
                  class="agent-pool-card"
                  :class="{ 'agent-pool-card--assigned': selectedPoolAgentIds.includes(p.agent.id) }"
                >
                  <q-card-section class="agent-pool-card__body">
                    <q-checkbox
                      :model-value="selectedPoolAgentIds.includes(p.agent.id)"
                      color="primary"
                      @update:model-value="(val) => togglePoolAgent(p.agent.id, val)"
                    />
                    <div class="agent-pool-card__info">
                      <div class="agent-pool-card__name">{{ agentNameFor(p.agent) }}</div>
                      <div class="agent-pool-card__desc text-caption text-grey-6 text-capitalize">{{ p.role }}</div>
                      <div v-if="p.skills_summary?.length" class="agent-pool-card__skills q-mt-xs">
                        <q-chip
                          v-for="skill in p.skills_summary.slice(0, 3)"
                          :key="skill"
                          size="xs"
                          outline
                          color="primary"
                          :label="skill"
                          dense
                        />
                        <span v-if="p.skills_summary.length > 3" class="text-caption text-grey-6">
                          +{{ p.skills_summary.length - 3 }}
                        </span>
                      </div>
                    </div>
                  </q-card-section>
                </q-card>
              </div>
              <div v-if="selectedPoolAgentIds.length" class="q-mt-md text-caption text-grey-6">
                {{ selectedPoolAgentIds.length }} agent{{ selectedPoolAgentIds.length === 1 ? '' : 's' }} selected
              </div>
            </q-tab-panel>

            <!-- Step 5/6: Configuration -->
            <q-tab-panel :name="configStepId" class="q-pa-none">
              <div class="step-title q-mb-sm">{{ $t('configuration') }}</div>
              <p class="step-subtitle q-mb-lg">
                {{ $t('config_step_desc') }}
              </p>
              <AgentConfigStep
                v-model="formData.config"
              />
            </q-tab-panel>
          </q-tab-panels>
        </div>

        <!-- Footer Navigation -->
        <div class="wizard-footer">
          <q-btn
            flat
            :label="$t('cancel')"
            color="primary"
            no-caps
            @click="$emit('cancel')"
          />
          <q-space />
          <q-btn
            v-if="step > 1"
            flat
            :label="$t('back')"
            color="primary"
            no-caps
            icon="arrow_back"
            class="q-mr-sm"
            @click="step--"
          />
          <!-- ``f-btn`` (FellowButton) used here because its
               ``--blocked`` style override re-enables pointer events
               on the disabled state, which lets the tooltip fire on
               hover (raw ``q-btn[disabled]`` blocks pointer events
               entirely and the tooltip never shows).  The right-side
               arrow is rendered via the default slot — f-btn renders
               its own ``icon`` prop on the left, so adding a slot
               icon places it after the label. -->
          <f-btn
            v-if="step < lastStepId"
            appearance="primary"
            :label="$t('next')"
            :blocked="!canProceed"
            @click="nextStep"
          >
            <q-icon name="arrow_forward" size="18px" class="q-ml-xs" />
            <q-tooltip v-if="!canProceed && nextDisabledReason">
              {{ nextDisabledReason }}
            </q-tooltip>
          </f-btn>
          <q-btn
            v-else
            unelevated
            color="primary"
            :label="$t('save_agent')"
            no-caps
            icon="check"
            :loading="saving"
            @click="saveAgent"
          />
        </div>
      </div>
    </div>
  </div>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { defineComponent, type PropType } from 'vue';
import { agentDisplayName, type AgentIdentity } from 'src/pages/DocNet/shared/docnet-labels';
import { useAgentsStore } from 'src/store/main';
import { useDocNetAgentStore } from 'src/store/DocNet/docnet-agents.store';
import { ApiExceptions } from 'src/exceptions';
import AgentBasicInfoStep from 'src/pages/Settings/Components/Agents/AgentBasicInfoStep.vue';
import AgentInstructionsStep from 'src/pages/Settings/Components/Agents/AgentInstructionsStep.vue';
import SkillSelector from 'src/pages/Settings/Components/Agents/SkillSelector.vue';
import AgentConfigStep from 'src/pages/Settings/Components/Agents/AgentConfigStep.vue';
import {
  AGENT_NAME_MAX_LENGTH,
  AGENT_DESCRIPTION_MAX_LENGTH,
  AGENT_DESCRIPTION_MIN_LENGTH_WHEN_REQUIRED,
  AGENT_PROMPT_MAX_LENGTH,
  AGENT_PROMPT_MIN_LENGTH,
} from 'src/pages/Settings/Components/Agents/agent-wizard-constants';
import type {
  Agent,
  AgentCreate,
  AgentSkill,
  AgentConfig,
  SkillDefinition,
} from 'src/@types/agents';

export interface FormData {
  name: string;
  description: string;
  system_prompt: string;
  document_types: string[];
  skills: AgentSkill[];
  tools: string[];
  mcp_servers: Record<string, string[]>;
  /** Buffered per-tool approval overrides — accumulated as the
   *  user clicks the settings cog on individual tools.  Persisted
   *  alongside the rest of the agent in the Save handler. */
  tool_approvals: Record<string, boolean>;
  config: AgentConfig;
  priority: number;
  is_enabled: boolean;
}

// Defaults match the backend ``AgentConfig`` (src/models/agent.py).
// DocBits agents are task-execution agents (classify, validate, extract,
// route), not creative writers — temperature 0.3 mirrors what every
// production system agent converged on.  60s timeouts were also too
// short: Document Processor runs routinely take >60s with extraction
// polling, so the wizard's old default would 504 every real agent
// before the work finished.  300s matches the backend default.
const defaultConfig: AgentConfig = {
  max_retries: 3,
  timeout_seconds: 300,
  log_interactions: true,
  require_approval: true,
  approval_mode: 'critical',
  model: 'docbits-pro',
  reasoning_effort: 'medium',
  max_tokens: 4096,
};

const getDefaultFormData = (): FormData => ({
  name: '',
  description: '',
  system_prompt: '',
  document_types: [],
  skills: [],
  tools: [],
  mcp_servers: {},
  tool_approvals: {},
  config: { ...defaultConfig },
  priority: 5,
  is_enabled: true,
});

export default defineComponent({
  name: 'AgentWizard',

  components: {
    AgentBasicInfoStep,
    AgentInstructionsStep,
    SkillSelector,
    AgentConfigStep,
  },

  props: {
    agent: {
      type: Object as PropType<Agent | null>,
      default: null,
    },
    isEdit: {
      type: Boolean,
      default: false,
    },
  },

  emits: ['saved', 'cancel'],

  setup() {
    const agentsStore = useAgentsStore();
    return { agentsStore };
  },

  data() {
    return {
      step: 1 as number,
      saving: false,
      formData: getDefaultFormData() as FormData,
      errors: {} as Record<string, string>,
      selectedPoolAgentIds: [] as string[],
      _placeholder: 0 as number, // steps moved to computed
    };
  },

  computed: {
    availableSkills(): SkillDefinition[] {
      return this.agentsStore.availableSkills;
    },
    docnetAgentStore() {
      return useDocNetAgentStore();
    },

    isOrchestrator(): boolean {
      return this.formData.config?.role === 'orchestrator';
    },

    steps(): { id: number; labelKey: string }[] {
      const base = [
        { id: 1, labelKey: 'basic_info' },
        { id: 2, labelKey: 'instructions' },
        { id: 3, labelKey: 'skills' },
      ];
      if (this.isOrchestrator) {
        base.push({ id: 4, labelKey: 'agent_pool' });
        base.push({ id: 5, labelKey: 'configuration' });
      } else {
        base.push({ id: 4, labelKey: 'configuration' });
      }
      return base;
    },

    configStepId(): number {
      return this.isOrchestrator ? 5 : 4;
    },

    lastStepId(): number {
      return this.steps[this.steps.length - 1].id;
    },

    poolAgents() {
      const excludeRoles = new Set(['orchestrator', 'router']);
      return this.docnetAgentStore.profiles.filter((p: any) => {
        return p.agent.is_enabled !== false && !excludeRoles.has(p.role) && p.agent.id !== this.agent?.id;
      });
    },

    canProceed(): boolean {
      switch (this.step) {
        case 1: {
          // Name: non-empty (required field, no minimum beyond that).
          // Description: must satisfy the same length threshold the
          // inline live error in AgentBasicInfoStep enforces, so the
          // Next button stays disabled while the live red message is
          // still visible — keeps the gate honest with what the UI
          // is telling the user.  Backend validator on AgentCreate
          // enforces the same minimum, so this is purely UX.
          const nameOk = this.formData.name.trim().length > 0;
          const descLen = (this.formData.description || '').trim().length;
          const descOk = descLen >= AGENT_DESCRIPTION_MIN_LENGTH_WHEN_REQUIRED;
          return nameOk && descOk;
        }
        case 2: {
          // Prompt: must satisfy the same min-length threshold the
          // inline live error in AgentInstructionsStep enforces.
          // Previously this gate was just "non-empty" — the user
          // could click Next on a 3-char prompt and only then see
          // the live error. Aligning to min-length here keeps the
          // gate consistent with the visual feedback.
          const promptLen = this.formData.system_prompt.trim().length;
          return promptLen >= AGENT_PROMPT_MIN_LENGTH;
        }
        default:
          return true;
      }
    },

    /** Tooltip text shown on the disabled Next button so the user
     *  knows WHY they can't proceed without trial-and-error.  Returns
     *  the empty string when ``canProceed`` is true; the template
     *  ``v-if`` then suppresses the tooltip entirely.  Lists every
     *  unmet requirement on the current step in one short line. */
    nextDisabledReason(): string {
      if (this.canProceed) return '';
      const reasons: string[] = [];
      if (this.step === 1) {
        if (!this.formData.name.trim()) {
          reasons.push(this.$t('agent_wizard_name_required') as string);
        }
        const descLen = (this.formData.description || '').trim().length;
        if (descLen < AGENT_DESCRIPTION_MIN_LENGTH_WHEN_REQUIRED) {
          reasons.push(
            this.$t('agent_wizard_description_too_short', {
              min: AGENT_DESCRIPTION_MIN_LENGTH_WHEN_REQUIRED,
            }) as string,
          );
        }
      } else if (this.step === 2) {
        const promptLen = this.formData.system_prompt.trim().length;
        if (promptLen < AGENT_PROMPT_MIN_LENGTH) {
          reasons.push(
            this.$t('agent_wizard_prompt_too_short', {
              min: AGENT_PROMPT_MIN_LENGTH,
            }) as string,
          );
        }
      }
      return reasons.join(' · ');
    },
  },

  watch: {
    agent: {
      handler(newAgent: Agent | null) {
        if (newAgent) {
          this.formData = {
            name: newAgent.name,
            description: newAgent.description || '',
            system_prompt: newAgent.system_prompt,
            document_types: [...newAgent.document_types],
            skills: [...newAgent.skills],
            tools: [...(newAgent.tools || [])],
            mcp_servers: JSON.parse(JSON.stringify(newAgent.mcp_servers || {})),
            tool_approvals: { ...(newAgent.config?.tool_approvals || {}) },
            config: { ...newAgent.config },
            priority: newAgent.priority,
            is_enabled: newAgent.is_enabled,
          };
        } else {
          this.formData = getDefaultFormData();
        }
        this.step = 1;
        this.errors = {};
      },
      immediate: true,
    },
  },

  mounted() {
    // Ensure DocNet agent profiles are loaded for the orchestrator pool selector
    if (!this.docnetAgentStore.profiles.length) {
      this.docnetAgentStore.fetchProfiles().catch(() => {});
    }
  },

  methods: {
    agentNameFor(agent: AgentIdentity): string {
      return agentDisplayName(this.$t, agent);
    },
    togglePoolAgent(agentId: string, selected: boolean): void {
      if (selected) {
        if (!this.selectedPoolAgentIds.includes(agentId)) {
          this.selectedPoolAgentIds.push(agentId);
        }
      } else {
        this.selectedPoolAgentIds = this.selectedPoolAgentIds.filter((id) => id !== agentId);
      }
    },

    canNavigate(stepId: number): boolean {
      if (this.isEdit) return true;
      if (stepId <= this.step) return true;
      if (stepId === this.step + 1) return this.canProceed;
      return false;
    },

    navigateToStep(stepId: number) {
      if (this.canNavigate(stepId)) {
        this.step = stepId;
      }
    },

    nextStep() {
      if (this.validateCurrentStep()) {
        this.step++;
      }
    },

    validateCurrentStep(): boolean {
      this.errors = {};
      switch (this.step) {
        case 1:
          if (!this.formData.name.trim()) {
            this.errors.name = this.$t('agent_wizard_name_required') as string;
            return false;
          }
          // Length checks mirror backend Pydantic constraints — see
          // ``agent-wizard-constants.ts``.  HTML ``maxlength`` clamps
          // typing but doesn't catch the case where pre-existing data
          // (e.g. on edit) somehow exceeds the limit, so we re-check here.
          if (this.formData.name.length > AGENT_NAME_MAX_LENGTH) {
            this.errors.name = this.$t(
              'agent_wizard_name_too_long',
              { max: AGENT_NAME_MAX_LENGTH },
            ) as string;
            return false;
          }
          if (
            this.formData.description
            && this.formData.description.length > AGENT_DESCRIPTION_MAX_LENGTH
          ) {
            this.errors.description = this.$t(
              'agent_wizard_description_too_long',
              { max: AGENT_DESCRIPTION_MAX_LENGTH },
            ) as string;
            return false;
          }
          // Description is required from this wizard, full stop.
          // Orchestrators are picked by the System Router from this
          // text; specialists are picked by their parent orchestrator
          // from it.  The router role isn't creatable through the
          // wizard (it's a single system-seeded agent), so we don't
          // carve out an "optional" branch.  Minimum length is set
          // in ``agent-wizard-constants.ts`` — a single word like
          // "validator" doesn't give the LLM enough signal to route
          // reliably.
          const role = this.formData.config?.role;
          const descriptionTrimmed = (this.formData.description || '').trim();
          if (!descriptionTrimmed) {
            this.errors.description = this.$t(
              role === 'orchestrator'
                ? 'agent_wizard_description_required_orchestrator'
                : 'agent_wizard_description_required_specialist',
            ) as string;
            return false;
          }
          if (descriptionTrimmed.length < AGENT_DESCRIPTION_MIN_LENGTH_WHEN_REQUIRED) {
            this.errors.description = this.$t(
              'agent_wizard_description_too_short',
              { min: AGENT_DESCRIPTION_MIN_LENGTH_WHEN_REQUIRED },
            ) as string;
            return false;
          }
          break;
        case 2:
          if (!this.formData.system_prompt.trim()) {
            this.errors.system_prompt = this.$t('agent_wizard_prompt_required') as string;
            return false;
          }
          if (this.formData.system_prompt.trim().length < AGENT_PROMPT_MIN_LENGTH) {
            this.errors.system_prompt = this.$t(
              'agent_wizard_prompt_too_short',
              { min: AGENT_PROMPT_MIN_LENGTH },
            ) as string;
            return false;
          }
          if (this.formData.system_prompt.length > AGENT_PROMPT_MAX_LENGTH) {
            this.errors.system_prompt = this.$t(
              'agent_wizard_prompt_too_long',
              { max: AGENT_PROMPT_MAX_LENGTH },
            ) as string;
            return false;
          }
          break;
      }
      return true;
    },

    async saveAgent() {
      if (!this.validateCurrentStep()) return;

      this.saving = true;
      try {
        // Merge buffered per-tool overrides into the agent's
        // ``config`` JSONB blob.  Backend expects them under
        // ``AgentConfig.tool_approvals``; the wizard stages them
        // outside config so the SkillSelector binding stays
        // simple, then we fold them in on save.
        const mergedConfig = {
          ...this.formData.config,
          tool_approvals: this.formData.tool_approvals || {},
        };

        const agentData: AgentCreate = {
          name: this.formData.name,
          description: this.formData.description || undefined,
          system_prompt: this.formData.system_prompt,
          document_types: this.formData.document_types,
          skills: this.formData.skills,
          tools: this.formData.tools,
          mcp_servers: this.formData.mcp_servers,
          mcp_tools: [],
          config: mergedConfig,
          priority: this.formData.priority,
          is_enabled: this.formData.is_enabled,
        };

        let savedAgentId: string | null = null;
        if (this.isEdit && this.agent) {
          await this.agentsStore.updateAgent(this.agent.id, agentData);
          savedAgentId = this.agent.id;
        } else {
          const created = await this.agentsStore.createAgent(agentData);
          savedAgentId = created?.id || null;
        }

        // Assign pool agents to this orchestrator
        if (savedAgentId && this.selectedPoolAgentIds.length && this.formData.config?.role === 'orchestrator') {
          for (const poolAgentId of this.selectedPoolAgentIds) {
            try {
              await this.docnetAgentStore.updateAgentReportsTo(poolAgentId, savedAgentId);
            } catch (e) {
              console.warn(`Failed to assign agent ${poolAgentId} to orchestrator:`, e);
            }
          }
        }

        this.$emit('saved');
      } catch (error: any) {
        console.error('Failed to save agent:', error);
        const msg = ApiExceptions.getErrorMessage(error);
        notify.error(msg);
      } finally {
        this.saving = false;
      }
    },
  },
});
</script>

